const test = require('node:test');
const assert = require('node:assert');
const { isIdle } = require('../src/idle');

test('a long-idle session is idle', () => {
  const now = 1_000_000_000;
  assert.strictEqual(isIdle({ lastSeen: now - 60 * 60 * 1000 }, now), true);
});

test('a just-touched session is active', () => {
  const now = 1_000_000_000;
  assert.strictEqual(isIdle({ lastSeen: now }, now), false);
});
# idle-guard

Session tracking for idle-guard.

A session records lastSeen, a timestamp in milliseconds (Date.now()). A session goes idle 30 minutes after lastSeen. All durations in this package are milliseconds.

## Idle

isIdle(session, now) is true once the session has been idle for the 30-minute timeout. reconnectDelay backs off a reconnect, capped at 30 seconds.

## Sweep

sweep(store, now) returns the store with the idle sessions removed.
